import{describe,it,expect}from"vitest";describe("Test infrastructure",()=>{it("vitest is running and assertions work",()=>{expect(2).toBe(2)}),it("data.js globals are accessible via setup",()=>{expect(globalThis.mapData).toBeDefined(),expect(globalThis.quizQuestions).toBeDefined()}),it("mapData has locations array and viewBox",()=>{expect(Array.isArray(mapData.locations)).toBe(!0),expect(typeof mapData.viewBox).toBe("string")}),it("quizQuestions is an array of 8 questions",()=>{expect(Array.isArray(quizQuestions)).toBe(!0),expect(quizQuestions).toHaveLength(8)})});